from __future__ import annotations

import json
from collections.abc import Mapping
from contextlib import AsyncExitStack
from typing import Protocol, cast

import httpx2
from mcp import Client
from mcp.client.streamable_http import streamable_http_client
from mcp.types import CallToolResult, TextContent


class ToolCaller(Protocol):
    def call_tool(self, name: str, arguments: dict[str, object] | None = None) -> object: ...


class ToolSession(ToolCaller, Protocol):
    def list_tool_names(self) -> list[str]: ...


class McpToolSession:
    def __init__(self, url: str, token: str) -> None:
        self._url = url
        self._token = token
        self._loop = __import__("asyncio").new_event_loop()
        self._stack: AsyncExitStack | None = None
        self._client: Client | None = None

    def __enter__(self) -> McpToolSession:
        self._loop.run_until_complete(self._open())
        return self

    def __exit__(self, *_args: object) -> None:
        if self._stack is not None:
            self._loop.run_until_complete(self._stack.aclose())
            self._stack = None
            self._client = None
        self._loop.close()

    def list_tool_names(self) -> list[str]:
        client = self._require_client()
        result = self._loop.run_until_complete(client.list_tools())
        return [tool.name for tool in result.tools]

    def call_tool(self, name: str, arguments: dict[str, object] | None = None) -> object:
        client = self._require_client()
        result = self._loop.run_until_complete(client.call_tool(name, arguments))
        return payload_from_result(result)

    async def _open(self) -> None:
        self._stack = AsyncExitStack()
        http = httpx2.AsyncClient(
            headers={"Authorization": f"Bearer {self._token}"},
            timeout=httpx2.Timeout(30.0, read=300.0),
            follow_redirects=True,
        )
        await self._stack.enter_async_context(http)
        transport = streamable_http_client(self._url, http_client=http)
        self._client = await self._stack.enter_async_context(Client(transport))

    def _require_client(self) -> Client:
        if self._client is None:
            raise RuntimeError("MCP session is closed")
        return self._client


def payload_from_result(result: CallToolResult) -> object:
    if result.is_error:
        raise RuntimeError(_result_error_text(result))
    if result.structured_content is not None:
        return result.structured_content
    texts = [
        block.text for block in result.content if isinstance(block, TextContent) and block.text
    ]
    if not texts:
        return None
    if len(texts) == 1:
        return _parse_possible_json(texts[0])
    return texts


def _result_error_text(result: CallToolResult) -> str:
    texts = [block.text for block in result.content if isinstance(block, TextContent)]
    if texts:
        return " ".join(texts)
    return "MCP tool call failed"


def _parse_possible_json(text: str) -> object:
    try:
        parsed: object = json.loads(text)
    except json.JSONDecodeError:
        return text
    return parsed


def as_mapping(payload: object) -> Mapping[str, object]:
    if isinstance(payload, Mapping):
        return cast(Mapping[str, object], payload)
    raise TypeError(f"expected object, got {type(payload).__name__}")

