from __future__ import annotations

import base64
import json
from collections.abc import Mapping, Sequence
from typing import TypeVar, cast

from pydantic import BaseModel

from supplier_loop.simulator.port import (
    Assignment,
    Attachment,
    EmailMessage,
    InboxEntry,
    PriceHistoryRow,
    SimClock,
    SubmitEcho,
    SupplierEntry,
)

T = TypeVar("T", bound=BaseModel)


def parse_assignment(payload: object) -> Assignment:
    data = _unwrap_object(payload, "assignment")
    return _validate(Assignment, data)


def parse_directory(payload: object) -> list[SupplierEntry]:
    items = _as_list(payload, "suppliers", "directory")
    return [_validate(SupplierEntry, _as_object(item)) for item in items]


def parse_price_history(payload: object) -> list[PriceHistoryRow]:
    items = _as_list(payload, "price_history", "history", "rows")
    return [_validate(PriceHistoryRow, _as_object(item)) for item in items]


def parse_clock(payload: object) -> SimClock:
    data = dict(_unwrap_object(payload, "clock"))
    if "clock_factor" not in data and "clockFactor" not in data:
        data["clock_factor"] = 1.0
    return _validate(SimClock, data)


def parse_inbox(payload: object) -> list[InboxEntry]:
    items = _as_list(payload, "inbox", "emails", "messages")
    return [parse_inbox_entry(item) for item in items]


def parse_inbox_entry(payload: object) -> InboxEntry:
    data = _as_object(payload)
    return InboxEntry(
        id=_require_str(data, "id"),
        from_address=_require_str(data, "from_address", "from", "fromAddress", "from_email"),
        to_address=_require_str(data, "to_address", "to", "toAddress", "to_email"),
        subject=_require_str(data, "subject"),
        sim_time_hours=_inbox_hours(data),
        attachment_ids=_attachment_ids(data),
    )


def parse_email(payload: object) -> EmailMessage:
    data = _unwrap_object(payload, "email", "message")
    entry = parse_inbox_entry(data)
    body = _optional_str(data, "body") or ""
    return EmailMessage(
        id=entry.id,
        from_address=entry.from_address,
        to_address=entry.to_address,
        subject=entry.subject,
        sim_time_hours=entry.sim_time_hours,
        attachment_ids=entry.attachment_ids,
        body=body,
    )


def parse_attachment(payload: object) -> Attachment:
    data = _unwrap_object(payload, "attachment")
    encoded = _optional_str(data, "base64", "content_base64")
    content = _optional_bytes(data, "content")
    if encoded is not None:
        content = base64.b64decode(encoded)
    if content is None:
        raise ValueError("attachment is missing content")
    return Attachment(
        id=_require_str(data, "id"),
        filename=_require_str(data, "filename", "name"),
        mime_type=_require_str(data, "mime_type", "mimeType"),
        content=content,
    )


def parse_send_id(payload: object) -> str:
    if payload is None:
        raise ValueError("send_email returned no id")
    if isinstance(payload, str) and payload:
        return payload
    data = _as_object(payload)
    return _require_str(data, "id", "email_id", "emailId")


def parse_echo(payload: object) -> SubmitEcho:
    if payload is None:
        return SubmitEcho(warnings=[])
    if isinstance(payload, list):
        return SubmitEcho(warnings=[str(item) for item in payload])
    data = _as_object(payload)
    raw = _get(data, "warnings")
    if raw is None:
        return SubmitEcho(warnings=[])
    if isinstance(raw, str):
        return SubmitEcho(warnings=[raw])
    if isinstance(raw, list):
        return SubmitEcho(warnings=[str(item) for item in raw])
    raise TypeError("warnings must be a list or string")


def _validate(model: type[T], data: Mapping[str, object]) -> T:
    picked: dict[str, object] = {}
    for name in model.model_fields:
        value = _get(data, name)
        if value is not None:
            picked[name] = value
    return model.model_validate(picked)


def _unwrap_object(payload: object, *keys: str) -> Mapping[str, object]:
    data = _as_object(payload)
    if len(data) == 1:
        key = next(iter(data))
        if key in keys or key in {"result", "data"}:
            inner = data[key]
            if isinstance(inner, Mapping):
                return cast(Mapping[str, object], inner)
    return data


def _as_list(payload: object, *keys: str) -> list[object]:
    payload = _maybe_json(payload)
    if isinstance(payload, list):
        return list(payload)
    data = _as_object(payload)
    for key in keys:
        value = _get(data, key)
        if isinstance(value, list):
            return list(value)
    raise TypeError(f"expected list, got {type(payload).__name__}")


def _as_object(payload: object) -> Mapping[str, object]:
    payload = _maybe_json(payload)
    if isinstance(payload, Mapping):
        return cast(Mapping[str, object], payload)
    raise TypeError(f"expected object, got {type(payload).__name__}")


def _maybe_json(payload: object) -> object:
    if isinstance(payload, str):
        try:
            parsed: object = json.loads(payload)
        except json.JSONDecodeError:
            return payload
        return parsed
    return payload


def _get(data: Mapping[str, object], *names: str) -> object | None:
    for name in names:
        if name in data:
            return data[name]
        camel = _camel(name)
        if camel in data:
            return data[camel]
    return None


def _require_str(data: Mapping[str, object], *names: str) -> str:
    value = _get(data, *names)
    if isinstance(value, str) and value:
        return value
    raise ValueError(f"missing string field {names[0]}")


def _optional_str(data: Mapping[str, object], *names: str) -> str | None:
    value = _get(data, *names)
    if isinstance(value, str):
        return value
    return None


def _optional_bytes(data: Mapping[str, object], *names: str) -> bytes | None:
    value = _get(data, *names)
    if isinstance(value, bytes):
        return value
    return None


def _inbox_hours(data: Mapping[str, object]) -> float:
    hours = _get(data, "sim_time_hours", "simTimeHours")
    if hours is not None:
        return float(cast(int | float | str, hours))
    seconds = _get(data, "sim_time_seconds", "simTimeSeconds")
    if seconds is not None:
        return float(cast(int | float | str, seconds)) / 3600.0
    raise ValueError("inbox entry missing sim time")


def _attachment_ids(data: Mapping[str, object]) -> list[str]:
    raw = _get(data, "attachment_ids", "attachmentIds", "attachments")
    if raw is None:
        return []
    if not isinstance(raw, list):
        raise TypeError("attachment_ids must be a list")
    ids: list[str] = []
    for item in cast(Sequence[object], raw):
        if isinstance(item, str):
            ids.append(item)
            continue
        if isinstance(item, Mapping):
            mapped = cast(Mapping[str, object], item)
            ids.append(_require_str(mapped, "id"))
            continue
        raise TypeError("attachment id must be a string")
    return ids


def _camel(name: str) -> str:
    parts = name.split("_")
    return parts[0] + "".join(part.title() for part in parts[1:])

from __future__ import annotations

from supplier_loop.simulator.port import (
    Assignment,
    Attachment,
    EmailMessage,
    InboxEntry,
    PriceHistoryRow,
    SentEmailRecord,
    SimClock,
    SubmitEcho,
    SubmitEntry,
    SupplierEntry,
)
from supplier_loop.simulator.session import ToolCaller
from supplier_loop.simulator.wire import (
    parse_assignment,
    parse_attachment,
    parse_clock,
    parse_directory,
    parse_echo,
    parse_email,
    parse_inbox,
    parse_price_history,
    parse_send_id,
)


class McpSimulator:
    def __init__(self, caller: ToolCaller) -> None:
        self._caller = caller
        self._sent: list[SentEmailRecord] = []
        self._last_echo: SubmitEcho | None = None

    def get_assignment(self) -> Assignment:
        return parse_assignment(self._caller.call_tool("get_assignment"))

    def get_supplier_directory(self) -> list[SupplierEntry]:
        return parse_directory(self._caller.call_tool("get_supplier_directory"))

    def get_price_history(self) -> list[PriceHistoryRow]:
        return parse_price_history(self._caller.call_tool("get_price_history"))

    def list_inbox(self, since_sim_time: float | None = None) -> list[InboxEntry]:
        arguments: dict[str, object] | None = None
        if since_sim_time is not None:
            arguments = {"since_sim_time": since_sim_time}
        return parse_inbox(self._caller.call_tool("list_inbox", arguments))

    def read_email(self, email_id: str) -> EmailMessage:
        return parse_email(self._caller.call_tool("read_email", {"email_id": email_id}))

    def download_attachment(self, attachment_id: str) -> Attachment:
        return parse_attachment(
            self._caller.call_tool("download_attachment", {"attachment_id": attachment_id})
        )

    def get_sim_clock(self) -> SimClock:
        return parse_clock(self._caller.call_tool("get_sim_clock"))

    def send_email(self, to: str, subject: str, body: str) -> str:
        email_id = parse_send_id(
            self._caller.call_tool("send_email", {"to": to, "subject": subject, "body": body})
        )
        self._sent.append(SentEmailRecord(id=email_id, to=to, subject=subject, body=body))
        return email_id

    def list_sent(self) -> list[SentEmailRecord]:
        return [
            SentEmailRecord(id=mail.id, to=mail.to, subject=mail.subject, body=mail.body)
            for mail in self._sent
        ]

    def submit_results(self, results: dict[str, SubmitEntry]) -> SubmitEcho:
        dumped = {supplier_id: entry.model_dump() for supplier_id, entry in results.items()}
        echo = parse_echo(self._caller.call_tool("submit_results", {"results": dumped}))
        self._last_echo = echo
        return echo

    def last_echo(self) -> SubmitEcho | None:
        return self._last_echo

    def request_dev_round(self) -> object:
        return self._caller.call_tool("request_dev_round")

from __future__ import annotations

import re

from supplier_loop.extract.schema import ExtractRequest, ExtractResult
from supplier_loop.round_state.models import QuoteLine

_QTY_LINE = re.compile(
    r"qty\s+([0-9][0-9.,]*)\s+(.+?)\s+([0-9][0-9.,]*)\s+USD",
    re.IGNORECASE,
)
_BULLET_LINE = re.compile(
    r"^[-*]\s+([0-9][0-9.,]*)\s+(\S+)\s+(.+?)\s+@\s+\$?\s*([0-9][0-9.,]*)\s+USD",
    re.IGNORECASE | re.MULTILINE,
)
_SKU = re.compile(r"\(([^)]+)\)\s*$")
_NET = re.compile(r"\bNet\s+(\d+)\b", re.IGNORECASE)
_VALID = re.compile(r"\bvalid(?:ity)?[^\d]{0,24}(\d+)\s*days", re.IGNORECASE)
_TOTAL = re.compile(
    r"\bTotal\b[^\d$]{0,24}\$?\s*([0-9][0-9.,]*)",
    re.IGNORECASE,
)


class CrudeExtractor:
    def extract(self, request: ExtractRequest) -> ExtractResult:
        lines = _parse_lines(request.body)
        payment = _first_int(_NET, request.body) or ""
        validity = _first_int(_VALID, request.body)
        stated = _first_decimal(_TOTAL, request.body)
        totals = [line.total for line in lines]
        grand = stated if stated is not None else sum(totals)
        return ExtractResult(
            line_items=lines,
            payment_terms=f"Net {payment}" if payment else "",
            validity_days=validity if validity is not None else 0,
            grand_total=grand,
            injection_suspected=False,
        )


def _parse_lines(body: str) -> list[QuoteLine]:
    bullets = [_bullet_line(match) for match in _BULLET_LINE.finditer(body)]
    if bullets:
        return bullets
    return [_qty_line(match) for match in _QTY_LINE.finditer(body)]


def _bullet_line(match: re.Match[str]) -> QuoteLine:
    quantity = parse_decimal(match.group(1))
    description = match.group(3).strip()
    unit_price = parse_decimal(match.group(4))
    sku_match = _SKU.search(description)
    material_id = sku_match.group(1) if sku_match else None
    if sku_match:
        description = description[: sku_match.start()].strip()
    total = round(quantity * unit_price, 2)
    return QuoteLine(
        material_id=material_id,
        description=description,
        quantity=quantity,
        unit_price=unit_price,
        total=total,
    )


def _qty_line(match: re.Match[str]) -> QuoteLine:
    quantity = parse_decimal(match.group(1))
    description = match.group(2).strip()
    unit_price = parse_decimal(match.group(3))
    total = round(quantity * unit_price, 2)
    return QuoteLine(
        material_id=None,
        description=description,
        quantity=quantity,
        unit_price=unit_price,
        total=total,
    )


def parse_decimal(raw: str) -> float:
    text = raw.strip().replace(" ", "").replace("$", "")
    if "," in text and "." in text:
        if text.rindex(",") > text.rindex("."):
            text = text.replace(".", "").replace(",", ".")
        else:
            text = text.replace(",", "")
    elif "," in text:
        _left, right = text.rsplit(",", 1)
        if len(right) == 3 and _left.replace(",", "").isdigit():
            text = text.replace(",", "")
        else:
            text = text.replace(",", ".")
    return float(text)


def _first_int(pattern: re.Pattern[str], body: str) -> str | None:
    match = pattern.search(body)
    if match is None:
        return None
    return match.group(1)


def _first_decimal(pattern: re.Pattern[str], body: str) -> float | None:
    match = pattern.search(body)
    if match is None:
        return None
    return parse_decimal(match.group(1))

