def run_until_submit(
    simulator: Simulator,
    store: RoundStore,
    extractor: Extractor,
    log: OperationalLog,
    *,
    progress: TextIO | None = None,
    max_passes: int = 20,
    pause_seconds: float = 0.0,
    sleeper: Callable[[float], None] | None = None,
) -> dict[str, SubmitEntry]:
